edits.insert:
// ── Межтрадиционная мостовость ──────────────────────────────
// Доля межтрадиционных связей среди ВНЕШНИХ. Единственная величина,
// которую традиции добавляют по-настоящему: корреляция рангов с общей
// степенью 0,11, с внешней 0,10 — почти ортогональна тому, что уже
// считается. Для сравнения, отвергнутые замыслы дали 0,84 (традиции
// истоков против философов-истоков в синтетичности) и 0,89 (традиции
// против философов в историческом охвате) — то есть переименование.
//
// ПОРОГ: доля неустойчива на малых знаменателях, три связи дают сто
// процентов. Ниже порога метрика равна нулю, и это видно в подробностях.
//
// ВАЖНО: величина опирается на РАЗМЕТКУ традиций, сделанную по
// содержанию, а не на измерение. Это сказано и в тексте формулы.
const BRIDGING_MIN_EXTERNAL = 3;
let traditionBridgingCache = null;

function traditionBridgingIndex(conceptId) {
  const concept = _conceptMap.get(conceptId);
  if (!concept) return { total: 0 };
  const own = concept.philosopher;
  const ownTraditions = (_philosopherMap.get(own) || {}).traditions || [];

  let external = 0, crossing = 0, crossWeight = 0, extWeight = 0;
  const reached = new Set();
  const links = [...(_outgoingLinks.get(conceptId) || []),
                 ...(_incomingLinks.get(conceptId) || [])];
  links.forEach(r => {
    const otherId = r.source === conceptId ? r.target : r.source;
    if (otherId === conceptId) return;
    const other = _conceptMap.get(otherId);
    if (!other || other.philosopher === own) return;
    external++;
    const w = r.weight || 2;
    extWeight += w;
    const ot = (_philosopherMap.get(other.philosopher) || {}).traditions || [];
    if (!ownTraditions.some(t => ot.includes(t))) {
      crossing++; crossWeight += w;
      ot.forEach(t => reached.add(t));
    }
  });

  const enough = external >= BRIDGING_MIN_EXTERNAL;
  // Доля показывается ПО ВЕСАМ — тою же мерой, какой считается сама
  // величина. Считать её по числу связей значило бы показывать в
  // подробностях не то, по чему построен рейтинг: у весов 1, 2 и 3
  // расхождение доходит до десятка процентов.
  const share = extWeight ? crossWeight / extWeight : 0;
  return {
    total: enough ? (crossWeight / Math.max(1, extWeight)) * 10 : 0,
    share: Math.round(share * 100),
    crossingLinks: crossing,
    externalLinks: external,
    traditionsReached: reached.size,
    belowThreshold: !enough
  };
}

function invalidateTraditionBridgingCache() {
  traditionBridgingCache = null;
}

function generateBridgingContent() {
  if (!concepts || !relations) {
    initializePhilosophyMetrics();
  }

  const results = nodes.map(n => {
    const metric = traditionBridgingIndex(n.id);
    return { node: n, value: metric.total, details: metric };
  }).filter(rankKeep).sort((a, b) => b.value - a.value);

  return generateMetricResults(
    results.slice(0, 30),
    '🌉 Межтрадиционная мостовость',
    'Концепции, чьи внешние связи ведут за пределы своей традиции',
    'bridging',
    'value',
    true
  );
}

